We need to output a single HTML file with CSS and JS inside. Must implement snake game with arrow keys or WASD, score display, restart after game over via key press, no external resources.

We'll write code: <html><head>... style ...</head><body> canvas etc. JS: set up canvas size 400x400 maybe. Snake array of segments, direction, speed. Food random position not on snake. Game loop using requestAnimationFrame. Input handling arrow keys or WASD.

When collision with wall (snake head x=0 or width-1) or self -> game over: stop loop, display "Game Over" and score. Press any key to restart.

We'll embed everything in one file.

Let's craft code:

<!DOCTYPE html>
<html lang="ru">
<head>
<meta charset="UTF-8">
<title>Змейка</title>
<style>
body{margin:0;overflow:hidden;background:#111;display:flex;justify-content:center;align-items:center;height:100vh;}
canvas{border:2px solid #fff;}
#score{position:absolute;top:10px;left:10px;font-size:24px;color:#fff;}
</style>
</head>
<body>
<canvas id="game" width="400" height="400"></canvas>
<div id="score">Счёт: 0</div>
<script>
const canvas=document.getElementById('game');
const ctx=canvas.getContext('2d');
let snake=[];
let direction='RIGHT';
let speed=10;
let score=0;
let food={x:Math.floor(Math.random()*39)+1,y:Math.floor(Math.random()*39)};
let gameRunning=true;

function draw(){
if(!gameRunning) return;
ctx.clearRect(0,0,canvas.width,canvas.height);
drawFood();
drawSnake();
requestAnimationFrame(draw);
}
function drawFood(){
ctx.fillStyle='lime';
ctx.fillRect(food.x*10,food.y*10,9,9);
}
function drawSnake(){
for(let i=0;i<snake.length;i++){
let x=snake[i].x*10;
let y=snake[i].y*10;
ctx.fillStyle='lime';
ctx.fillRect(x,y,9,9);
if(i===snake.length-1) ctx.strokeStyle='black'; else ctx.strokeStyle='none';
ctx.strokeRect(x,y,9,9);
}
}
function update(){
let head={x:snake[0].x+getDirectionX(direction),y:snake[0].y+getDirectionY(direction)};
if(head.x<0||head.x>39||head.y<0||head.y>39){
gameRunning=false;
alert('Game Over! Счёт: '+score);
return;
}
for(let i=1;i<snake.length;i++){
if(snake[i].x===head.x&&snake[i].y===head.y){
gameRunning=false;
return;
}
}
snake.unshift(head);
if(head.x===food.x && head.y===food.y){
snake.pop();
score++;
food={x:Math.floor(Math.random()*39)+1,y:Math.floor(Math.random()*39)};
while(snake.some(seg=>seg.x===food.x&&seg.y===food.y)){
food={x:Math.floor(Math.random()*39)+1,y:Math.floor(Math.random()*39)};
}
}else{
snake.pop();
}
}
function getDirectionX(dir){
if(dir==='RIGHT') return 1;
if(dir==='LEFT') return -1;
return 0;
}
function getDirectionY(dir){
if(dir==='DOWN') return 1;
if(dir==='UP') return -1;
return 0;
}
document.addEventListener('keydown',e=>{
let key=e.key.toLowerCase();
if(key==='w'||key==='ArrowUp'){
direction='UP';
}else if(key==='s'||key==='ArrowDown'){
direction='DOWN';
}else if(key==='a'||key==='ArrowLeft'){
direction='LEFT';
}else if(key==='d'||key==='ArrowRight'){
direction='RIGHT';
}
});
function restart(){
snake=[{x:18,y:18}];
score=0;
food={x:Math.floor(Math.random()*39)+1,y:Math.floor(Math.random()*39)};
while(snake.some(seg=>seg.x===food.x&&seg.y===food.y)){
food={x:Math.floor(Math.random()*39)+1,y:Math.floor(Math.random()*39)};
}
gameRunning=true;
}
document.addEventListener('keypress',restart);
draw();
</script>
</body>
</html>

Check that restart works on any key press after game over. Might need to stop requestAnimationFrame? We just set gameRunning false and alert; then pressing any key calls restart which sets snake, score, food, gameRunning true. But the animation loop will continue because draw() still runs but gameRunning false stops drawing? Actually we call draw() only if !gameRunning return; So after game over, draw returns early each frame, no further updates. That's okay.

But need to ensure that after restart, direction maybe default 'RIGHT' fine.

Potential issue: when game over, requestAnimationFrame still pending but draw returns early, so loop stops. Good.

